//! Region inference: a region is a set of program points.
//!
//! Two kinds of constraints determine the regions:
//!
//! * *liveness constraints*: if a local is live at a point, every region in
//!   its type contains that point (the lexical checker uses "in scope"
//!   instead of "live");
//! * *outlives constraints* `'a: 'b`, generated by assignments, borrows and
//!   calls: the region `'a` must contain every point of `'b`.
//!
//! The solution is the smallest assignment of point sets that satisfies all
//! of them, found by iterating to a fixpoint.

use std::collections::{BTreeMap, BTreeSet};

use crate::dataflow::solve;
use crate::liveness::{Liveness, LocalSet, MaybeStorageLive};
use crate::mir::*;

// ANCHOR: constraint
/// `sup: sub`, generated at `location`: the region `sup` must outlive (as a
/// set of points: contain) the region `sub`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct OutlivesConstraint {
    pub sup: RegionVid,
    pub sub: RegionVid,
    pub location: Location,
}
// ANCHOR_END: constraint

/// Relate a value of type `src` flowing into a place of type `dst`:
/// `&'a T` may flow into `&'b T` only if `'a: 'b` (Chapter 27: references
/// are covariant in their region; `&mut T` is invariant in `T`).
fn relate(src: &Ty, dst: &Ty, location: Location, out: &mut Vec<OutlivesConstraint>) {
    match (src, dst) {
        (Ty::Ref(a, m, t1), Ty::Ref(b, _, t2)) => {
            out.push(OutlivesConstraint {
                sup: *a,
                sub: *b,
                location,
            });
            relate(t1, t2, location, out);
            if *m == Mutability::Mut {
                relate(t2, t1, location, out);
            }
        }
        (Ty::Adt(_, xs), Ty::Adt(_, ys)) => {
            for (x, y) in xs.iter().zip(ys) {
                relate(x, y, location, out);
            }
        }
        _ => {}
    }
}

// ANCHOR: constraints
/// Generate the outlives constraints of a body.
pub fn outlives_constraints(body: &Body) -> Vec<OutlivesConstraint> {
    let mut out = Vec::new();
    for location in body.locations() {
        let block = &body.blocks[location.block.0];
        match block.statements.get(location.index) {
            Some(Statement {
                kind: StatementKind::Assign(dest, rv),
                ..
            }) => {
                let dest_ty = body.place_ty(dest);
                match rv {
                    Rvalue::Use(Operand::Copy(p) | Operand::Move(p)) => {
                        relate(&body.place_ty(p), &dest_ty, location, &mut out);
                    }
                    Rvalue::Ref(k, kind, borrowed) => {
                        // The rvalue `&'k p` has type `&'k T`; it flows into `dest`.
                        let m = match kind {
                            BorrowKind::Shared => Mutability::Not,
                            _ => Mutability::Mut,
                        };
                        let rv_ty = Ty::Ref(*k, m, Box::new(body.place_ty(borrowed)));
                        relate(&rv_ty, &dest_ty, location, &mut out);
                        // Reborrow: borrowing `*r` (where `r: &'r T`) for `'k`
                        // requires `'r: 'k`, so the original loan outlives the new one.
                        let mut ty = body.decl(borrowed.local).ty.clone();
                        for elem in &borrowed.projection {
                            if let (ProjectionElem::Deref, Ty::Ref(r, _, _)) =
                                (elem, &ty)
                            {
                                out.push(OutlivesConstraint {
                                    sup: *r,
                                    sub: *k,
                                    location,
                                });
                            }
                            ty = ty.project(*elem);
                        }
                    }
                    _ => {}
                }
            }
            Some(_) => {}
            None => {
                if let TerminatorKind::Call {
                    args,
                    dest,
                    result_borrows_from: Some(i),
                    ..
                } = &block.terminator.kind
                {
                    // The signature ties the result to argument `i`: every
                    // region of the argument outlives every region of the result.
                    let arg_ty = args[*i].place().map(|p| body.place_ty(p));
                    let dest_ty = body.place_ty(dest);
                    for a in arg_ty.map(|t| t.regions()).unwrap_or_default() {
                        for d in dest_ty.regions() {
                            out.push(OutlivesConstraint {
                                sup: a,
                                sub: d,
                                location,
                            });
                        }
                    }
                }
            }
        }
    }
    out
}
// ANCHOR_END: constraints

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum RegionMode {
    /// A reference keeps its loan alive while it is *in scope* (Rust 2015).
    Lexical,
    /// A reference keeps its loan alive while it is *live* (NLL).
    Nll,
}

/// The value of each region: a set of points, plus `end('r)` markers for the
/// named regions it must outlive (they stand for "the rest of the caller").
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RegionValues {
    pub points: Vec<BTreeSet<Location>>,
    pub ends: Vec<BTreeSet<RegionVid>>,
}

impl RegionValues {
    pub fn contains(&self, r: RegionVid, loc: Location) -> bool {
        self.points[r.0].contains(&loc)
    }

    /// Print a region value the way rustc's `-Zdump-mir=nll` does:
    /// `{bb1[3..=7], bb2[0..=1]}`.
    pub fn describe(&self, body: &Body, r: RegionVid) -> String {
        let mut parts = Vec::new();
        if self.points[r.0].len() == body.locations().len() {
            parts.push("every point".to_string());
        } else {
            parts.extend(describe_points(&self.points[r.0]));
        }
        for end in &self.ends[r.0] {
            parts.push(format!("end({})", body.region_name(*end)));
        }
        format!("{{{}}}", parts.join(", "))
    }
}

/// Compress a set of points into ranges: `bb1[3..=7]`, `bb5[0]`.
pub fn describe_points(points: &BTreeSet<Location>) -> Vec<String> {
    let mut parts = Vec::new();
    let mut iter = points.iter().peekable();
    while let Some(&first) = iter.next() {
        let mut last = first;
        while let Some(&&next) = iter.peek() {
            if next.block == last.block && next.index == last.index + 1 {
                last = next;
                iter.next();
            } else {
                break;
            }
        }
        if first == last {
            parts.push(format!("{first}"));
        } else {
            parts.push(format!("{}[{}..={}]", first.block, first.index, last.index));
        }
    }
    parts
}

/// For each point, the locals that keep their regions alive there: the live
/// locals (NLL) or the locals in scope (lexical).
pub fn alive_locals(body: &Body, mode: RegionMode) -> BTreeMap<Location, LocalSet> {
    match mode {
        RegionMode::Nll => solve(body, Liveness).states_before(body),
        RegionMode::Lexical => solve(body, MaybeStorageLive).states_before(body),
    }
}

// ANCHOR: liveness_constraints
/// The liveness constraints: the starting value of every region.
pub fn initial_values(body: &Body, mode: RegionMode) -> RegionValues {
    let n = body.regions.len();
    let mut points = vec![BTreeSet::new(); n];
    let mut ends = vec![BTreeSet::new(); n];
    // A region in the type of a live (or in-scope) local contains the point.
    for (loc, locals) in alive_locals(body, mode) {
        for local in locals {
            for r in body.decl(local).ty.regions() {
                points[r.0].insert(loc);
            }
        }
    }
    // A borrow's region contains the point where the borrow happens.
    for loc in body.locations() {
        if let Some(Statement {
            kind: StatementKind::Assign(_, Rvalue::Ref(k, _, _)),
            ..
        }) = body.blocks[loc.block.0].statements.get(loc.index)
        {
            points[k.0].insert(loc);
        }
    }
    // A named region outlives the whole body, and itself.
    for r in body.universal_regions() {
        points[r.0] = body.locations().into_iter().collect();
        ends[r.0].insert(r);
    }
    RegionValues { points, ends }
}
// ANCHOR_END: liveness_constraints

// ANCHOR: propagate
/// Grow the regions until every outlives constraint holds. Returns the
/// solution and the number of passes over the constraints.
pub fn propagate(
    mut values: RegionValues,
    constraints: &[OutlivesConstraint],
) -> (RegionValues, usize) {
    let mut passes = 0;
    loop {
        passes += 1;
        let mut changed = false;
        for c in constraints {
            // 'sup: 'sub  means  value('sup) ⊇ value('sub)
            let sub_points = values.points[c.sub.0].clone();
            let sub_ends = values.ends[c.sub.0].clone();
            let before = (values.points[c.sup.0].len(), values.ends[c.sup.0].len());
            values.points[c.sup.0].extend(sub_points);
            values.ends[c.sup.0].extend(sub_ends);
            changed |=
                before != (values.points[c.sup.0].len(), values.ends[c.sup.0].len());
        }
        if !changed {
            return (values, passes);
        }
    }
}
// ANCHOR_END: propagate

/// Region inference for a body: constraints, solution, number of passes.
pub struct RegionInference {
    pub constraints: Vec<OutlivesConstraint>,
    pub values: RegionValues,
    pub passes: usize,
}

pub fn infer(body: &Body, mode: RegionMode) -> RegionInference {
    let constraints = outlives_constraints(body);
    let (values, passes) = propagate(initial_values(body, mode), &constraints);
    RegionInference {
        constraints,
        values,
        passes,
    }
}

/// The regions reachable from `start` in the constraint graph (`'a: 'b` is
/// an edge from `'a` to `'b`): every region whose points `start` must contain.
pub fn reachable(
    constraints: &[OutlivesConstraint],
    start: RegionVid,
) -> BTreeSet<RegionVid> {
    let mut seen = BTreeSet::from([start]);
    let mut work = vec![start];
    while let Some(r) = work.pop() {
        for c in constraints.iter().filter(|c| c.sup == r) {
            if seen.insert(c.sub) {
                work.push(c.sub);
            }
        }
    }
    seen
}
